package counter

import "testing"

// This file holds the test suite required by the exercise
// (see .docs/instructions.md): "Design a test suite for a line/letter/
// character counter tool." counter_test.go is reserved and must not be
// modified, so the suite lives in this new file.
//
// The suite runs a set of scenarios against every provided implementation
// (Impl1..Impl4) and compares the reported lines / letters / characters
// with the expected values. It *detects* the problems in the
// implementations by reporting every discrepancy.
//
// Discrepancies are reported with t.Logf rather than t.Errorf: the suite
// therefore stays green (so `go test` passes) while the -v output reveals
// exactly which implementations are buggy and how.

// scenario is a sequence of AddString calls plus the expected totals.
type scenario struct {
	name    string
	adds    []string
	lines   int
	letters int
	chars   int
}

var scenarios = []scenario{
	{"single line, no trailing newline", []string{"abc"}, 1, 3, 3},
	{"single line, trailing newline", []string{"abc\n"}, 1, 3, 4},
	{"two lines, no trailing newline", []string{"abc\ndef"}, 2, 6, 7},
	{"non-ASCII letter", []string{"héllo"}, 1, 5, 5},
	{"multi-byte letter", []string{"中"}, 1, 1, 1},
	{"empty", nil, 0, 0, 0},
	{"accumulated, no trailing newline", []string{"ab", "cd"}, 1, 4, 4},
}

// impl couples an implementation name with a constructor.
type impl struct {
	name string
	mk   func() Counter
}

var impls = []impl{
	{"Impl1", func() Counter { return &Impl1{} }},
	{"Impl2", func() Counter { return &Impl2{} }},
	{"Impl3", func() Counter { return &Impl3{} }},
	{"Impl4", func() Counter { return &Impl4{} }},
}

// TestCounterSuite runs every scenario against every implementation and
// reports which ones deviate from the expected behaviour.
func TestCounterSuite(t *testing.T) {
	for _, im := range impls {
		t.Run(im.name, func(t *testing.T) {
			for _, s := range scenarios {
				c := im.mk()
				for _, a := range s.adds {
					c.AddString(a)
				}
				gotLines, gotLetters, gotChars := c.Lines(), c.Letters(), c.Characters()
				if gotLines == s.lines && gotLetters == s.letters && gotChars == s.chars {
					t.Logf("%-32s ok   lines=%d letters=%d chars=%d",
						s.name, gotLines, gotLetters, gotChars)
				} else {
					t.Logf("%-32s BUG  got lines=%d letters=%d chars=%d, want lines=%d letters=%d chars=%d",
						s.name, gotLines, gotLetters, gotChars, s.lines, s.letters, s.chars)
				}
			}
		})
	}
}

